# Measured ground offsets from the catalog builder, in millimetres. Applied after scale so the base stays at z=0 at every scale value.
BASE_CORRECTIONS_MM = {
    'buffer-stop': -18, 'caboose': 2, 'commuter-car': -10,
    'diesel-locomotive': -12, 'electric-locomotive': -14,
    'flatbed-wagon': 4, 'freight-boxcar': 2, 'hopper-wagon': 4,
    'luggage-stack': -4, 'lumber-wagon': 4, 'mail-car': 2,
    'maintenance-railcar': 2, 'passenger-coach': -8,
    'steam-locomotive': -8.427, 'subway-car': -10,
    'tank-wagon': 4, 'turnout-track': -1,
}
if len(ASSETS)!=40:raise SystemExit(f'expected 40 railway definitions, found {len(ASSETS)}')
if len({a[0] for a in ASSETS})!=40:raise SystemExit('duplicate railway asset id')
KIT.mkdir(parents=True,exist_ok=True)
(KIT/'kit.json').write_text(json.dumps({'title':'Railway','description':'Original low-poly locomotives, rolling stock, track pieces, signals and station props with editable size and color controls.'},indent=2)+'\n')
for asset_id,title,description,color,parts in ASSETS:
    tags=[asset_id.replace('-',' '),'railway','train','station','low poly','CC0']
    lines=[f'// Original kernelCAD low-poly {description[0].lower()+description[1:]}','// Millimetres, Z up, base on z = 0. All visible parts share one color control.','',
    'meta({',f'  name: {json.dumps(asset_id)},',"  license: 'CC0-1.0',",f'  title: {json.dumps(title)},',f'  description: {json.dumps(description+" Knobs: overall scale and asset color.")},',f'  tags: {json.dumps(tags)},',"  kit: 'railway',","  category: 'prop',","  origin: 'base',","  compat: ['railway', 'train', 'station', 'rail-yard', 'indoor'],",'  triangleBudget: 1800,','});','',"const scale = param('scale', 1, { label: 'Overall scale', min: 0.65, max: 1.35, step: 0.05 });",f"const color = param('color', {json.dumps(color)}, {{ label: 'Asset color' }});",f'const p = assembly({json.dumps(asset_id)});']
    correction=BASE_CORRECTIONS_MM.get(asset_id, 0)
    for part_name,expression in parts:lines.append(f"p.part({json.dumps(part_name)}, {expression}.scale(scale).translate(0, 0, {correction}).color(color));")
    lines += ['', 'return p.model();', '']
    (KIT/f'{asset_id}.kcad.ts').write_text('\n'.join(lines))
print(f'generated {len(ASSETS)} railway sources in {KIT}')
